/bin/bash -lc "python3 - <<'PY'
import subprocess,json
x=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
print('ROOT',list(x)); print('CONTEXT',list(x.get('context',{})))
for k,v in x.items():
 if k"'!='"'context': print(k,json.dumps(v))
c=x['context']
for k,v in c.items():
 if k not in ('history','trajectory_index'): print(k,json.dumps(v))
for h in c['history']:
 d={k:v for k,v in h.items() if k not in ('validation','candidate_diagnostics')}
 v=h.get('validation') or {}
 d['validation']={k:z for k,z in v.items() if k"'!='"'slices'}
 d['diagnostics']=h.get('candidate_diagnostics')
 print('TRIAL',json.dumps(d))
PY"

