import json,subprocess,math
from pathlib import Path
p=Path('/workspace/analysis.json')
a=json.loads(p.read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
ids={t['id'] for t in r['context']['trajectory_index']}
required=['observations','interpretations','alternatives','falsifiers','evidence_refs','next_action','limitations']
assert all(k in a for k in required)
assert a['phase']=='analyze' and a['protocol_hash']==r['context']['protocol']['identity']
assert set(a['evidence_refs'])==ids
assert len(a['performance_and_cost_table'])==len(ids)==17
assert all(any(x.startswith('r0004-') for x in o['evidence_refs']) for o in a['observations'] if o['id'] in ['O6','O7','O8'])
def walk(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if k=='evidence_refs': assert isinstance(v,list) and set(v)<=ids,(k,v)
   walk(v)
 elif isinstance(x,list):
  for v in x: walk(v)
walk(a)
rows={t['id']:t for t in a['performance_and_cost_table']}
for c in a['contrasts']+a['bridge_checks']:
 for name,key in [('auc','validation_auc'),('logloss','validation_logloss')]:
  assert math.isclose(c['delta_'+name],rows[c['candidate']][key]-rows[c['reference']][key],abs_tol=1e-15)
h={t['id']:t for t in r['context']['history']}
for t in a['performance_and_cost_table']:
 if t['current_direct_detailed_receipt']:
  z=h[t['id']]
  assert t['source_sha256']==z['source_sha256'] and t['config']==z['config']
  assert t['validation_auc']==z['validation']['auc'] and t['validation_logloss']==z['validation']['logloss']
i=h['r0004-inline_same_field']['candidate_diagnostics']['values']
j=h['r0003-same_field_product']['candidate_diagnostics']['values']
assert len(j)==57 and all(i[k]==v for k,v in j.items())
assert i['inline_helper_logit_abs_max']==0
for pair in a['bridge_checks']:
 x=h[pair['candidate']]['validation'];y=h[pair['reference']]['validation']
 assert x['slices']==y['slices']
 assert x['auc']==y['auc'] and x['logloss']==y['logloss']
for s in a['slice_table']:
 assert s['samples']==s['positives']+s['negatives']
 for tid,m in s['metrics'].items():
  assert m['auc']==h[tid]['validation']['slices'][s['slice']]['auc']
  assert m['logloss']==h[tid]['validation']['slices'][s['slice']]['logloss']
q=['r0003-same_field_product','r0003-cross_only','r0003-context_only','r0003-ordinary_product']
for name,key in [('auc','validation_auc'),('logloss','validation_logloss')]:
 expected=rows[q[0]][key]-rows[q[1]][key]-rows[q[2]][key]+rows[q[3]][key]
 assert math.isclose(a['factorial_interactions']['product']['delta_'+name],expected,abs_tol=1e-15)
c=a['next_action']['cost'];cap=r['context']['protocol']['trial_cap_seconds']
assert c['followup_seconds_at_caps']==12*cap
assert c['provisional_final_reserve_seconds_at_caps']==18*cap
assert c['residual_after_followup_caps_and_final_reserve_seconds']>=0
print(json.dumps({'status':'passed','artifact':str(p),'bytes':p.stat().st_size,'trials':len(ids),'observations':len(a['observations']),'slice_rows':len(a['slice_table']),'common_diagnostic_values_equal':len(j),'no_withheld_feedback':r['context']['no_test_feedback']}))
PY"

